n("ריבה", "ריבה היא צורת חיבה ביידיש של רבקה. בקהילות של מזרח אירופה נפוצו הרבה צורות קצרות של שמות עבריים, ורבקה הפכה שם לריבקה, לריווה ולריבה. השם ניתן לבנות, ובארץ הוא נדיר היום.", [])
n("יום", "יום הוא שם עברי קצר ופשוט, מהמילה יום, הזמן שבו השמש זורחת. יש הורים שבוחרים בו כשם של אור וזמן חדש. השם נדיר מאוד, והוא ניתן בעיקר לבנים. מאותו עולם של טבע ושל זמן באים גם השמות שחר ובוקר.", ["שחר"])
n("צאלה", "צאלה היא עץ שיטה רחב ונמוך שגדל בערבה ובמדבר, ונותן צל במקום חם ויבש. השם בא מאותו שורש כמו המילה צל. צאלה ניתן לבנות, והוא שייך לקבוצה של שמות עבריים מעולם הצמחים, כמו שיטה ואלה.", ["שיטה", "אלה"])
n("בטי", "בטי היא צורת חיבה אנגלית של אליזבת, שבא מהשם העברי אלישבע, אלי נשבע. השם היה נפוץ מאוד באנגליה ובאמריקה באמצע המאה העשרים. בארץ השם נדיר, והוא ניתן לבנות. מוכרות גם הצורות בת׳ ובס.", ["אלישבע"])
n("עמינדב", "עמינדב הוא שם מקראי שבנוי מהמילים עמי ונדב, העם שלי נדיב. בתורה עמינדב הוא אביו של נחשון, נשיא שבט יהודה, ואביה של אלישבע אשת אהרן. השם ניתן לבנים, והוא נשמע עתיק ומכובד. מוכרת גם הצורה הקצרה נדב.", ["נדב", "נחשון"])
n("נל", "נל הוא שם אנגלי קצר, צורת חיבה של הלן ושל אלינור. השם היה נפוץ באנגליה בתקופה הוויקטוריאנית, ובשנים האחרונות הוא חזר להיות אופנתי. בארץ הוא נשמע קרוב לשמות נלי ונילי. השם ניתן לבנות.", ["נלי", "נילי"])
n("לאיו", "לאיו הוא שם חדש ונדיר, וכנראה הוא צורה של לאו או של ליאו, שם לטיני שפירושו אריה. בעברית הצליל שלו קרוב לשמות לאה ולאיה. השם ניתן לבנים, והוא נשמע בינלאומי וקליל.", ["ליאו", "לאו"])
n("נטליה", "נטליה הוא שם שבא מהמילה הלטינית נטליס, יום הולדת, ובמקור הוא קשור ליום של חג המולד. השם נפוץ ברוסית, בפולנית ובשפה הספרדית. בארץ הוא הגיע עם העלייה, ומוכרת גם הצורה נטלי.", ["נטלי"])
n("הלנה", "הלנה הוא שם יווני עתיק שפירושו כנראה זוהרת או אור. במיתולוגיה היוונית הלנה היא היפה בנשים, שבגללה פרצה מלחמת טרויה. השם נפוץ בשפות רבות באירופה, ובעברית מוכרות גם הצורות הלן ואלנה.", ["הלן", "הלני"])
n("סיימון", "סיימון הוא הצורה האנגלית של שמעון, שם מקראי מהשורש ש־מ־ע, שמיעה. השם נפוץ באנגליה ובצרפת, שם הוא נכתב סימון. בארץ השם נשמע בינלאומי, וקרוב אליו גם השם סימונה. השם ניתן לבנים.", ["שמעון", "סימונה"])
n("בן-אל", "בן־אל הוא שם עברי חדש שבנוי מהמילים בן ואל, ופירושו בן של אלוהים. השם קרוב לשמות כמו בניה ובן, שמבטאים קשר בין האדם לאלוהים. בן־אל ניתן לבנים, והוא נדיר בארץ.", ["בנאל", "בן"])
n("ניסל", "ניסל הוא שם ביידיש שפירושו אגוז קטן. ביידיש השתמשו בשמות של פירות ושל טבע כשמות חיבה, והסיומת ל מוסיפה רוך וחיבה. השם ניתן לבנות, והוא נדיר מאוד היום.", [])
n("סמי", "סמי הוא צורת חיבה של שמואל, ובארצות שונות גם של שמות אחרים כמו סמואל ושלמה. בארץ השם היה נפוץ בקרב עולים מארצות המזרח ומצפון אפריקה. השם ניתן לבנים, והוא נשמע חם וקליל.", ["שמואל", "סמואל"])
n("רענן", "רענן הוא שם עברי מהמילה רענן, צעיר ומלא חיים, כמו עץ ירוק שגדל ליד מים. השם נשמע טבעי וחי, והוא היה נפוץ בארץ בשנות החמישים והשישים. רענן ניתן לבנים, וקרובים אליו שמות של טבע כמו אילן ואלון.", ["אילן", "אלון"])
n("כתריאל", "כתריאל הוא שם עברי שבנוי מהמילים כתר ואל, ופירושו הכתר של אלוהים. בקבלה כתר הוא הגבוהה בספירות. השם ניתן לבנים, והוא נדיר יחסית, אבל נשמע מכובד ושמח. מוכר גם השם הקצר כתר.", ["כתר"])
n("אולי", "אולי הוא שם אנגלי קצר, צורת חיבה של אוליבר ושל אוליביה. בעברית המילה אולי היא גם מילה של ספק ותקווה, ולכן לשם יש צליל משחקי. השם ניתן גם לבנים וגם לבנות, והוא נדיר בארץ.", ["אוליבר", "אוליביה"])
n("ניה", "ניה היא צורת חיבה רוסית של אנה, ובשפות אחרות גם של שמות כמו אנטוניה. בעברית השם נשמע קרוב לנויה ולנוי. השם ניתן לבנות, והוא קצר ופשוט לבטא בכל שפה.", ["נויה", "אנה"])
n("פעשא", "פעשא הוא שם ביידיש, וכנראה הוא צורת חיבה של בתיה, דרך הצורות פייגא ופעסיה. בקהילות של מזרח אירופה נפוצו צורות רבות כאלה של שמות עבריים. השם ניתן לבנות, והוא נדיר מאוד היום.", ["בתיה"])
n("מאטל", "מאטל הוא שם ביידיש, וכנראה הוא צורה של מטילדה, שם גרמני עתיק שפירושו חזקה בקרב. ביידיש נבנו צורות חיבה רבות עם הסיומת ל. השם ניתן לבנות, והוא נדיר מאוד היום.", [])
n("אביבית", "אביבית הוא שם עברי מהמילה אביב, העונה שבה הכול פורח. מאותה מילה באים גם השמות אביב ואביבה. השם היה נפוץ בארץ בשנות החמישים והשישים, והוא ניתן לבנות.", ["אביב", "אביבה"])
n("סלע", "סלע הוא שם עברי מהמילה סלע, אבן גדולה וחזקה. השם מביא תמונה של יציבות ושל כוח, והוא שייך לקבוצה של שמות מעולם הטבע כמו צור ואבן. השם ניתן בעיקר לבנים, וקרובה אליו צורת הנקבה סלעית.", ["סלעית", "צור"])
n("אירית", "אירית היא צמח בר עם פרחים לבנים שפורח בארץ בחורף. השם עברי, והוא שייך לגל של שמות פרחים שנפוצו בארץ בשנות החמישים והשישים, כמו נורית וכלנית. השם ניתן לבנות.", ["נורית", "כלנית"])
n("מוטי", "מוטי הוא צורת חיבה של מרדכי, שם שמקורו כנראה בשם האל הבבלי מרדוך. השם היה נפוץ מאוד בארץ בשנות החמישים והשישים. מוטי ניתן לבנים, והוא נשמע חם ופשוט.", ["מרדכי"])
n("רוזי", "רוזי הוא שם אנגלי, צורת חיבה של רוז, ורד. בעברית השם נשמע קרוב לרז, ובקהילות ביידיש מוכרים השמות רייזל ורוזה. השם ניתן לבנות, והוא נשמע קליל ושמח.", ["רוז", "רוזה"])
n("אילאיל", "אילאיל הוא שם עברי חדש, וכנראה הוא בנוי מהמילים איל ואל, או מהמילה אילה בתוספת אל. השם נשמע מוזיקלי, עם צליל חוזר. השם ניתן לבנות, והוא נדיר בארץ.", ["אליאל"])
n("זהבית", "זהבית הוא שם עברי מהמילה זהב. מאותה מילה באים גם השמות זהבה וזהבי. השם היה נפוץ בארץ בשנות החמישים והשישים, והוא ניתן לבנות. יש בו תחושה של אור ושל דבר יקר.", ["זהבה"])
n("ידין", "ידין הוא שם עברי מהשורש ד־י־ן, ופירושו ישפוט. בברכת יעקב לבניו נאמר על דן שהוא ידין את עמו. השם ניתן לבנים, והוא היה מוכר בארץ במיוחד בדור של קום המדינה. מאותו שורש באים גם השמות דן ודניאל.", ["דן", "דניאל"])
n("פסי", "פסי הוא צורת חיבה ביידיש של בתיה, דרך הצורה פסיה. בקהילות של מזרח אירופה צורות כאלה היו נפוצות מאוד, וחלקן הפכו לשמות בפני עצמם. השם ניתן לבנות, והוא נדיר היום.", ["פסיה", "בתיה"])
n("מוסיא", "מוסיא הוא שם ביידיש וברוסית, וכנראה הוא צורת חיבה של משה או של מרים. בקהילות חב״ד השם נפוץ יותר, בגלל אשתו של הרבי מלובביץ׳, חיה מושקא. השם ניתן לבנות.", ["מושקא"])
n("ירדנה", "ירדנה הוא שם עברי, צורת נקבה של ירדן, הנהר שזורם מהגליל לים המלח. השם היה נפוץ בארץ בשנות הארבעים והחמישים. ירדנה ניתן לבנות, ומאותה מילה בא גם השם ירדן.", ["ירדן"])
n("מירית", "מירית הוא שם עברי חדש, וכנראה הוא צורה של מירה ושל מרים. יש שקושרים אותו גם למילה מור, צמח בושם. השם היה נפוץ בארץ בשנות השישים, והוא ניתן לבנות.", ["מירה", "מירי"])
n("סימונה", "סימונה הוא הצורה הנשית של סימון, שבא מהשם העברי שמעון, מהשורש ש־מ־ע. השם נפוץ באיטלקית, ברומנית ובצרפתית, שם הוא נכתב סימון. בארץ השם נדיר יחסית, והוא ניתן לבנות.", ["סיימון"])
n("יזהר", "יזהר הוא שם עברי מהמילה זוהר, ופירושו יזרח ויאיר. השם נשמע ספרותי, והוא מוכר בארץ גם בזכות הסופר ס. יזהר, שזה היה שם העט שלו. השם ניתן לבנים.", ["זוהר"])
n("קתרין", "קתרין הוא שם בינלאומי ממקור יווני, ויש שקושרים אותו למילה קתרוס, טהור. השם נפוץ באנגלית ובצרפתית, וברוסית מוכרת הצורה יקטרינה. בארץ השם נדיר יחסית, והוא ניתן לבנות.", [])
n("ארן", "ארן הוא עץ האורן בכתיב המקראי. בספר ישעיהו נזכר ארן בין העצים שהאדם נוטע והגשם מגדל. השם ניתן לבנים, והוא נשמע קצר וטבעי. בעברית של היום מוכרים יותר השמות אורן ואורנה.", ["אורן", "אורנה"])
n("מאילי", "מאילי הוא שם חדש ונדיר, וכנראה הוא צורה של מאיה או של מאי. בעברית הצליל שלו רך וקליל. השם ניתן לבנות, וקרובים אליו השמות מאי ומאיה.", ["מאיה", "מאי"])
n("לורה", "לורה הוא שם לטיני שבא מהמילה לאורוס, עץ הדפנה. ביוון וברומא עלי דפנה היו סימן של ניצחון ושל כבוד. השם נפוץ בשפות רבות באירופה, והוא ניתן לבנות. מוכרת גם הצורה לורן.", ["לורן", "לורי"])
n("אלקה", "אלקה הוא שם ביידיש ובגרמנית, צורת חיבה של אדלהייד, שם גרמני עתיק שפירושו אצילה. השם היה נפוץ בקהילות של מרכז אירופה ומזרחה. השם ניתן לבנות, והוא נדיר היום.", [])
n("ליגל", "ליגל הוא שם עברי חדש שבנוי מהמילים לי וגל, ופירושו הגל שלי. השם שייך לקבוצה של שמות כמו ליאור וליאם, שמתחילים במילה לי. השם ניתן לבנות, והוא נשמע מודרני וקליל.", ["גל", "ליאור"])
n("לי-אל", "לי־אל הוא שם עברי חדש שבנוי מהמילים לי ואל, ופירושו האל שלי. השם קרוב לשמות כמו ליאל וליה, והוא נשמע רך ושמח. השם ניתן לבנות, והוא נדיר בארץ.", ["ליאל", "לי-יה"])
n("ברקאי", "ברקאי הוא שם עברי שבא מהמילה ברקאי, אור הבוקר הראשון. בתלמוד מסופר שבמקדש היו מחכים שהאיר ברקאי כדי להתחיל בעבודה. השם ניתן לבנים, והוא נשמע עתיק ובהיר. מאותה מילה בא גם השם ברק.", ["ברק"])
n("העני", "העני היא צורת חיבה ביידיש של חנה, שם שפירושו חן. ביידיש נבנו הרבה צורות חיבה של חנה, כמו חנקה והענא. השם ניתן לבנות, והוא נדיר מאוד היום.", ["הענא", "חנה"])
n("דורית", "דורית הוא שם עברי מהמילה דור, ויש שקושרים אותו גם לשם היווני דוריס. השם היה נפוץ מאוד בארץ בשנות החמישים והשישים. דורית ניתן לבנות, ומאותה מילה באים גם השמות דור ודורין.", ["דור", "דוריה"])
n("רוית", "רוית הוא שם עברי מהמילה רוויה, מלאה ושופעת, כמו אדמה שקיבלה גשם. השם היה נפוץ בארץ בשנות השישים והשבעים. רוית ניתן לבנות, ומוכר גם הכתיב רווית.", ["רווית"])
n("יראת", "יראת הוא שם עברי חדש ונדיר, מהמילה יראה, כבוד ופחד מתוך הערכה. השם נשמע רציני ומכובד. השם ניתן לבנות, וקרובים אליו בצליל השמות יורית ויראל.", ["יורית", "יראל"])
n("ניקו", "ניקו הוא קיצור של ניקולס, שם יווני שבנוי מהמילים ניקה, ניצחון, ולאוס, עם. השם נפוץ באיטלקית, ביוונית ובשפה הספרדית. בארץ הוא נשמע קליל ובינלאומי, והוא ניתן לבנים.", ["ניק", "ניקה"])
n("סיגלית", "סיגלית הוא שם עברי מהמילה סיגלית, פרח סגול וריחני שנקרא גם ויולה. מאותו פרח בא גם השם סיגל. השם היה נפוץ בארץ בשנות השישים והשבעים, והוא ניתן לבנות.", ["סיגל"])
n("ניבה", "ניבה הוא שם עברי מהמילה ניב, דיבור או ביטוי. מאותה מילה באים גם השמות ניב וניבי. השם נשמע רך וקצר, והוא ניתן לבנות. יש בו גם קשר למילה נוב, פרי ויבול.", ["ניב", "ניבי"])
n("חווה", "חווה היא האישה הראשונה בסיפור הבריאה. בספר בראשית האדם קורא לה חווה כי היא אם כל חי, ושמה קשור למילה חיים. השם ניתן לבנות, והוא נפוץ בעיקר בקהילות דתיות. מוכר גם הכתיב חוה.", ["חוה", "חיה"])
n("פראדי", "פראדי הוא שם ביידיש, וכנראה הוא צורה של פרידה, שפירושו שמחה ביידיש. ביידיש פריידע ופריידל הם שמות של שמחה. השם ניתן לבנות, והוא נדיר מאוד היום.", [])
